def effective_limit(value, default=10):
    if value is None:
        return default
    if value == 0:
        return 0
    if value < 0:
        raise ValueError("negative limit not allowed")
    return value

import sys
from settings import effective_limit

def test_none():
    assert effective_limit(None, default=10) == 10

def test_zero():
    assert effective_limit(0) == 0

def test_positive():
    assert effective_limit(5) == 5

def test_negative_raises():
    try:
        effective_limit(-1)
        assert False, "should raise ValueError"
    except ValueError:
        pass

if __name__ == "__main__":
    test_none()
    test_zero()
    test_positive()
    test_negative_raises()
    print("All tests passed")
